(7698218, 1262911, 173844, '<td valign="top">Lush, confusing, windblown, sculptural, bold use of shape and tone.  Can you really go home again?<br/>Personal co-favorite of the challenge.</td>', 'Lush, confusing, windblown, sculptural, bold use of shape and tone.  Can you really go home again?Personal co-favorite of the challenge.', '2021-07-30 00:31:15.000000', NULL, 1),
(7698220, 1262879, 173844, '<td valign="top">Last, or first, light brokering the peace.  Stars doing pinholes in the night.  That orange moon and its companion throwing meteor tails of reflection.  How many ways can clouds be beautiful?  Here''s one.  A fine distillation that thrives on understatement.<br/>Personal co-favorite of the challenge.</td>', 'Last, or first, light brokering the peace.  Stars doing pinholes in the night.  That orange moon and its companion throwing meteor tails of reflection.  How many ways can clouds be beautiful?  Here''s one.  A fine distillation that thrives on understatement.Personal co-favorite of the challenge.', '2021-07-30 00:40:11.000000', NULL, 1),
(7698221, 1262993, 173844, '<td valign="top">But for the trees we''d be disoriented.  A lovely organic splatter, dynamic yet serene.</td>', 'But for the trees we''d be disoriented.  A lovely organic splatter, dynamic yet serene.', '2021-07-30 00:43:50.000000', NULL, 1),
